import{_ as s,o as e,c as l,a5 as n}from"./chunks/framework.DfywBLEo.js";const o="/Cnblogs-Theme-SimpleMemory/v2.1/dist/images/install/install_03.png",r="/Cnblogs-Theme-SimpleMemory/v2.1/dist/images/install/install_02.png",p="/Cnblogs-Theme-SimpleMemory/v2.1/dist/images/install/install_05.png",u=JSON.parse('{"title":"安装配置","description":"","frontmatter":{},"headers":[],"relativePath":"guide/install.md","filePath":"guide/install.md","lastUpdated":1792557099000}'),t={name:"guide/install.md"};function i(c,a,m,h,d,b){return e(),l("div",null,[...a[0]||(a[0]=[n('<h1 id="安装配置" tabindex="-1">安装配置 <a class="header-anchor" href="#安装配置" aria-label="Permalink to &quot;安装配置&quot;">​</a></h1><p>需要先开通博客园 <strong>JS 权限</strong>。以下说明适用于 v2；v1 的配置不能直接沿用。</p><h2 id="选择版本" tabindex="-1">选择版本 <a class="header-anchor" href="#选择版本" aria-label="Permalink to &quot;选择版本&quot;">​</a></h2><p>在 <a href="https://github.com/BNDong/Cnblogs-Theme-SimpleMemory/releases" target="_blank" rel="noreferrer">Releases</a> 中选择版本，使用该版本的 CSS 和 JavaScript。下面以 <code>v2.1.7</code> 为例，安装其他版本时请同步替换版本号。</p><h2 id="博客园后台设置" tabindex="-1">博客园后台设置 <a class="header-anchor" href="#博客园后台设置" aria-label="Permalink to &quot;博客园后台设置&quot;">​</a></h2><p>打开<a href="https://i.cnblogs.com/Configure.aspx" target="_blank" rel="noreferrer">博客园设置</a>。</p><h3 id="皮肤和控件" tabindex="-1">皮肤和控件 <a class="header-anchor" href="#皮肤和控件" aria-label="Permalink to &quot;皮肤和控件&quot;">​</a></h3><ul><li>博客皮肤选择 <code>SimpleMemory</code>。</li><li>在「选项 → 控件显示设置」中开启需要显示的侧边栏栏目，例如随笔分类、我的标签和随笔档案。</li><li>栏目没有数据时，可能不会显示；具体见<a href="./menuData.html">侧边栏数据</a>。</li></ul><p><img src="'+o+'" alt="后台控件显示设置"></p><h3 id="代码高亮" tabindex="-1">代码高亮 <a class="header-anchor" href="#代码高亮" aria-label="Permalink to &quot;代码高亮&quot;">​</a></h3><p>后台的代码高亮设置如下：</p><ul><li>渲染引擎：<code>highlight.js</code>。</li><li>关闭「显示行号」和「Mac 风格」，由插件配置控制。</li><li>浅色主题选择 <code>cnblogs</code>，关闭跟随系统自动切换深浅主题。</li><li>不勾选「禁用默认代码高亮」。</li></ul><p>插件也可以使用自己的高亮主题，见<a href="/Cnblogs-Theme-SimpleMemory/v2.1/dist/reference/config/code.html">代码配置</a>。</p><p><img src="'+r+'" alt="后台代码高亮设置"></p><h3 id="页面定制-css" tabindex="-1">页面定制 CSS <a class="header-anchor" href="#页面定制-css" aria-label="Permalink to &quot;页面定制 CSS&quot;">​</a></h3><ol><li>勾选「禁用模板默认 CSS」。</li><li>打开 <a href="https://github.com/BNDong/Cnblogs-Theme-SimpleMemory/blob/v2.1.7/dist/simpleMemory.css" target="_blank" rel="noreferrer">v2.1.7 的 simpleMemory.css</a>，复制完整文件内容。</li><li>将内容填入「页面定制 CSS 代码」。安装其他版本时，先切换到对应版本再复制。</li></ol><p><img src="'+p+`" alt="页面定制 CSS 输入位置"></p><h3 id="博客侧边栏公告" tabindex="-1">博客侧边栏公告 <a class="header-anchor" href="#博客侧边栏公告" aria-label="Permalink to &quot;博客侧边栏公告&quot;">​</a></h3><p>将下面的代码填入「博客侧边栏公告」。昵称、入园日期和头像需要改成自己的信息，头像使用可公开访问的 HTTPS 图片地址。</p><div class="language-html line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">html</span><pre class="shiki simplememory-plum vp-code" tabindex="0"><code><span class="line"><span style="color:#EEE6F7;">&lt;</span><span style="color:#F0ADC4;">script</span><span style="color:#EEE6F7;">&gt;</span></span>
<span class="line"><span style="color:#EEE6F7;">window.</span><span style="color:#F0ADC4;">cnblogsConfig</span><span style="color:#F0ADC4;"> =</span><span style="color:#EEE6F7;"> {</span></span>
<span class="line"><span style="color:#EEE6F7;">  info: {</span></span>
<span class="line"><span style="color:#EEE6F7;">    name: </span><span style="color:#D1B4FA;">&#39;你的昵称&#39;</span><span style="color:#EEE6F7;">,</span></span>
<span class="line"><span style="color:#EEE6F7;">    startDate: </span><span style="color:#D1B4FA;">&#39;2021-01-01&#39;</span><span style="color:#EEE6F7;">,</span></span>
<span class="line"><span style="color:#EEE6F7;">    avatar: </span><span style="color:#D1B4FA;">&#39;https://example.com/avatar.png&#39;</span><span style="color:#EEE6F7;">,</span></span>
<span class="line"><span style="color:#EEE6F7;">  },</span></span>
<span class="line"><span style="color:#EEE6F7;">};</span></span>
<span class="line"><span style="color:#EEE6F7;">&lt;/</span><span style="color:#F0ADC4;">script</span><span style="color:#EEE6F7;">&gt;</span></span>
<span class="line"><span style="color:#EEE6F7;">&lt;</span><span style="color:#F0ADC4;">script</span><span style="color:#F0ADC4;"> src</span><span style="color:#EEE6F7;">=</span><span style="color:#D1B4FA;">&quot;https://cdn.jsdelivr.net/gh/BNDong/Cnblogs-Theme-SimpleMemory@v2.1.7/dist/simpleMemory.js&quot;</span><span style="color:#F0ADC4;"> defer</span><span style="color:#EEE6F7;">&gt;&lt;/</span><span style="color:#F0ADC4;">script</span><span style="color:#EEE6F7;">&gt;</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br><span class="line-number">10</span><br></div></div><p>配置应放在插件脚本之前。页面只引入一次插件；添加其他配置时，合并到同一个 <code>window.cnblogsConfig</code> 对象中。</p><p>也可以<a href="./resourceCdn.html">托管完整的插件资源</a>，然后替换脚本地址。</p><h2 id="保存并检查" tabindex="-1">保存并检查 <a class="header-anchor" href="#保存并检查" aria-label="Permalink to &quot;保存并检查&quot;">​</a></h2><p>保存设置，刷新博客，确认头图、侧边栏和文章页正常显示。接着可以按<a href="/Cnblogs-Theme-SimpleMemory/v2.1/dist/reference/configs.html">配置参考</a>调整外观和功能。</p><p>如果没有变化，先看<a href="./faq.html">常见问题</a>。升级已有安装请看<a href="./versionSwitch.html">版本切换</a>。</p>`,25)])])}const g=s(t,[["render",i]]);export{u as __pageData,g as default};
